      victim.rebalanced = true;
      return {
        moved: true,
        shiftId: victim.id,
        from: from,
        to: quietest.id,
        busiest: busiest.id,
        quietest: quietest.id,
        fairnessIndex: this.fairnessIndex(),
      };
    }
  }

  return {
    timezoneOffsetHours: timezoneOffsetHours,
    localHour: localHour,
    jainIndex: jainIndex,
    OnCallScheduler: OnCallScheduler,
  };
});

