 team.schedule.forEach(function(s){if(s.engineerId===engineerId){s.engineerId=null;s.engineerName='Unassigned';}});
 return team;
}
function convertToLocalTime(utcISO,offsetHours){
 var d=new Date(utcISO);
 if(isNaN(d.getTime()))throw new Error('Invalid date');
 return new Date(d.getTime()+offsetHours*3600000).toISOString();
}
function getHandoffDisplay(shift){
 function fmt(iso){var d=new Date(iso);return String(d.getUTCHours()).padStart(2,'0')+':'+String(d.getUTCMinutes()).padStart(2,'0');}
 var engLabel='';
 if(shift.timezoneLabel) engLabel=' ('+shift.timezoneLabel+')';
 else if(shift.timezoneOffset!==undefined){var o=shift.timezoneOffset;engLabel=' (UTC'+(o>=0?'+'+o:o)+')';}
 return 'UTC '+fmt(shift.startUTC)+' \u2192 Local '+fmt(shift.localStart)+engLabel;
}
function generateSchedule(team,startDateISO,days,options){
 if(!team||!team.engineers.length)throw new Error('Team must have at least 1 engineer');
 if(!startDateISO||isNaN(new Date(startDateISO).getTime()))throw new Error('Invalid start date');
 if(typeof days!=='number'||days<1||days>60)throw new Error('Days must be 1-60');
 var dur=(options&&options.shiftDurationHours)||12;
 if([8,12,24].indexOf(dur)===-1)throw new Error('Invalid shift duration');
 var shiftsPerDay=Math.floor(24/dur);
 var totalShifts=days*shiftsPerDay;
 var start=new Date(startDateISO);
 var hoursMap={};
 team.engineers.forEach(function(e){hoursMap[e.id]=0;});
 var schedule=[];
 for(var i=0;i<totalShifts;i++){
  var sUTC=new Date(start.getTime()+i*dur*3600000);
  var eUTC=new Date(sUTC.getTime()+dur*3600000);
  var sorted=team.engineers.slice().sort(function(a,b){return hoursMap[a.id]-hoursMap[b.id];});
  var eng=sorted[0];
  hoursMap[eng.id]+=dur;
  var localStart=convertToLocalTime(sUTC.toISOString(),eng.timezoneOffset);
  var localEnd=convertToLocalTime(eUTC.toISOString(),eng.timezoneOffset);
  var day=sUTC.getUTCDay();
  var hr=sUTC.getUTCHours();
  schedule.push({
   id:generateId(),date:sUTC.toISOString().slice(0,10),startUTC:sUTC.toISOString(),endUTC:eUTC.toISOString(),
   engineerId:eng.id,engineerName:eng.name,localStart:localStart,localEnd:localEnd,
   durationHours:dur,timezoneOffset:eng.timezoneOffset,timezoneLabel:eng.timezoneLabel,
   isNight:hr>=22||hr<6,isWeekend:day===0||day===6
  });
 }
 schedule.sort(function(a,b){return new Date(a.startUTC)-new Date(b.startUTC);});
 team.schedule=schedule;
 team.engineers.forEach(function(e){e.totalHours=hoursMap[e.id];e.shiftCount=schedule.filter(function(s){return s.engineerId===e.id;}).length;});
 return schedule;
}
function validateSchedule(schedule){
 var gaps=[],overlaps=[];
 var sorted=schedule.slice().sort(function(a,b){return new Date(a.startUTC)-new Date(b.startUTC);});
 for(var i=1;i<sorted.length;i++){
  var prev=new Date(sorted[i-1].endUTC).getTime();
  var cur=new Date(sorted[i].startUTC).getTime();
  if(cur>prev) gaps.push({index:i,from:sorted[i-1].endUTC,to:sorted[i].startUTC});
  if(cur<prev) overlaps.push({index:i,a:sorted[i-1].id,b:sorted[i].id});
 }
 return{valid:gaps.length===0&&overlaps.length===0,gaps:gaps,overlaps:overlaps};
}
function exportScheduleCSV(schedule){
 var h='Date,StartUTC,EndUTC,Engineer,DurationHours,LocalStart';
 var rows=schedule.map(function(s){return [s.date,s.startUTC,s.endUTC,s.engineerName,s.durationHours,s.localStart].join(',');});
 return [h].concat(rows).join('\n');
}
function calculateEngineerLoad(team,engineerId){
 var shifts=team.schedule.filter(function(s){return s.engineerId===engineerId;});
 var totalHours=shifts.reduce(function(a,s){return a+s.durationHours;},0);
 var incs=team.incidents.filter(function(x){return x.engineerId===engineerId;});
 var incidentLoad=incs.reduce(function(a,x){return a+(x.fatiguePoints||0);},0);
 return{shiftCount:shifts.length,totalHours:totalHours,incidentCount:incs.length,incidentLoad:incidentLoad,totalLoad:totalHours+incidentLoad};
}
function calculateFairnessIndex(team){
 var n=team.engineers.length;
 if(n===0) return 1;
 var loads=team.engineers.map(function(e){return calculateEngineerLoad(team,e.id).totalLoad;});
 var sum=loads.reduce(function(a,b){return a+b;},0);
 if(sum===0) return 1;
 var sumSq=loads.reduce(function(a,b){return a+b*b;},0);
 if(sumSq===0) return 1;
 var j=(sum*sum)/(n*sumSq);
 return Math.max(0,Math.min(1,j));
}
function maxStreak(schedule,engineerId){
 var sorted=schedule.slice().sort(function(a,b){return new Date(a.startUTC)-new Date(b.startUTC);});
 var max=0,cur=0;
 sorted.forEach(function(s){if(s.engineerId===engineerId){cur++;if(cur>max)max=cur;}else cur=0;});
