   upcoming[i].engineerId=least.engineerId;
   upcoming[i].engineerName=least.engineerName;
   if(leastEng){upcoming[i].timezoneOffset=leastEng.timezoneOffset;upcoming[i].timezoneLabel=leastEng.timezoneLabel;upcoming[i].localStart=convertToLocalTime(upcoming[i].startUTC,leastEng.timezoneOffset);upcoming[i].localEnd=convertToLocalTime(upcoming[i].endUTC,leastEng.timezoneOffset);}
   count++;
  }
 }
 var newFairness=calculateFairnessIndex(team);
 return{swaps:swaps,oldFairness:oldFairness,newFairness:newFairness,reason:'Swapped '+swaps.length+' shifts from '+most.engineerName+' to '+least.engineerName};
}
App.generateId=generateId;App.createEngineer=createEngineer;App.createTeam=createTeam;App.addEngineer=addEngineer;App.removeEngineer=removeEngineer;App.convertToLocalTime=convertToLocalTime;App.generateSchedule=generateSchedule;App.getHandoffDisplay=getHandoffDisplay;App.validateSchedule=validateSchedule;App.exportScheduleCSV=exportScheduleCSV;App.calculateEngineerLoad=calculateEngineerLoad;App.calculateFairnessIndex=calculateFairnessIndex;App.calculateFatigueScore=calculateFatigueScore;App.getFatigueReport=getFatigueReport;App.logIncident=logIncident;App.autoRebalance=autoRebalance;
if(typeof module!=='undefined'&&module.exports) module.exports=App;
if(typeof globalThis!=='undefined') globalThis.AppCore=App;
if(typeof window!=='undefined') window.OnCallApp=App;
