<header><h1>On-Call Scheduler</h1><div>Fairness: <b id="fair">100</b></div></header>
<div class="card"><h3>Roster</h3><input id="ename" placeholder="Name"><input id="eoff" type="number" step="0.5" value="0" style="width:80px"><input id="erole" placeholder="Role" style="width:100px"><button onclick="addEng()">Add</button><div id="roster"></div></div>
<div class="card"><h3>Schedule</h3><input id="sdate" type="date" value="2025-01-06"><input id="sdays" type="number" value="7" style="width:60px"><select id="sdur"><option value="8">8h</option><option value="12" selected>12h</option><option value="24">24h</option></select><button onclick="gen()">Generate</button><button onclick="reb()">Rebalance</button><button onclick="csv()">CSV</button><div id="grid"></div><div id="rpt" style="font-size:.8rem;color:var(--mut)"></div></div>
<div class="card"><h3>Fatigue</h3><div id="fatigue"></div></div>
<div class="card"><h3>Incident</h3><select id="ieng"></select><select id="isev"><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select><input id="idur" type="number" placeholder="mins" value="30" style="width:70px"><input id="idesc" placeholder="desc"><button onclick="logI()">Log</button></div>
<script src="app.js"></script>
<script>
var team=AppCore.createTeam('Alpha');
function refresh(){
 document.getElementById('fair').textContent=Math.round(AppCore.calculateFairnessIndex(team)*100);
 var r=document.getElementById('roster');r.innerHTML=team.engineers.map(e=>e.name+' ('+e.timezoneLabel+') <a href="#" onclick="delE(\''+e.id+'\')">x</a>').join(' | ');
 var sel=document.getElementById('ieng');sel.innerHTML=team.engineers.map(e=>'<option value="'+e.id+'">'+e.name+'</option>').join('');
 var g=document.getElementById('grid');g.innerHTML=team.schedule.map(s=>'<div class="shift" style="background:'+color(s.engineerId)+'" title="'+AppCore.getHandoffDisplay(s)+'">'+s.date+' '+s.engineerName+'<br><small>'+AppCore.getHandoffDisplay(s)+'</small></div>').join('');
 var f=document.getElementById('fatigue');f.innerHTML=AppCore.getFatigueReport(team).map(x=>'<div>'+x.engineerName+': '+x.fatigueScore+' ('+x.level+')<div class="bar"><div class="fill" style="width:'+x.fatigueScore+'%"></div></div></div>').join('');
}
function color(id){if(!id)return'#333';var h=0;for(var i=0;i<id.length;i++)h=(h*31+id.charCodeAt(i))%360;return 'hsl('+h+',60%,30%)';}
function addEng(){try{AppCore.addEngineer(team,{name:ename.value,timezoneOffset:parseFloat(eoff.value),role:erole.value});refresh();}catch(e){alert(e.message)}}
function delE(id){AppCore.removeEngineer(team,id);refresh();}
function gen(){try{AppCore.generateSchedule(team,new Date(sdate.value).toISOString(),parseInt(sdays.value),{shiftDurationHours:parseInt(sdur.value)});refresh();}catch(e){alert(e.message)}}
function reb(){var r=AppCore.autoRebalance(team);document.getElementById('rpt').textContent=r.reason+' swaps:'+r.swaps.length;refresh();}
function csv(){var c=AppCore.exportScheduleCSV(team.schedule);var b=new Blob([c],{type:'text/csv'});var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='schedule.csv';a.click();}
